msg.payload = `
SELECT p.id, p.sku, p.name, p.unit_price, p.weight_kg,
       c.name AS category_name
FROM products p
LEFT JOIN categories c ON c.id = p.category_id
WHERE p.is_active = true
ORDER BY p.created_at
`;
return msg;

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return v;
  return "'" + String(v).replace(/'/g, "''") + "'";
}
const rows = msg.payload;
if (!rows || rows.length === 0) {
  msg.payload = 'SELECT 1';
  return msg;
}
const vals = rows.map(r =>
  `(${esc(String(r.id))},${esc(r.sku)},${esc(r.name)},${esc(r.category_name)},${r.unit_price||0},${r.weight_kg||0})`
).join(',');
msg.payload = `MERGE dim_products AS t USING (VALUES ${vals}) AS s(source_id,sku,name,category,unit_price,weight_kg) ON t.source_id=s.source_id AND t.is_current=1 WHEN MATCHED THEN UPDATE SET t.name=s.name,t.category=s.category,t.unit_price=s.unit_price,t.weight_kg=s.weight_kg WHEN NOT MATCHED THEN INSERT(source_id,sku,name,category,unit_price,weight_kg,is_current,effective_from) VALUES(s.source_id,s.sku,s.name,s.category,s.unit_price,s.weight_kg,1,GETDATE());`;
return msg;

