function fmtDate(d){if(!d)return null;return new Date(d).toISOString().split('T')[0];}
const rows = msg.payload||[];
const pMap = msg.productMap||{};
const zMap = msg.zoneMap||{};
const sMap = msg.supplierMap||{};
const mvRows = [];
const ordRows = [];
rows.forEach(r => {
  const pk = pMap[String(r.product_id)];
  const zk = zMap[String(r.zone_id)];
