  if (!pk||!zk||!dateStr) return;
  mvRows.push(`(${pk},${zk},(SELECT time_key FROM dim_time WHERE full_date='${dateStr}'),${sk||'NULL'},'Inbound',${r.received_qty},0,${r.received_qty},${esc(r.reference_number)})`);
  ordRows.push(`(${pk},(SELECT time_key FROM dim_time WHERE full_date='${dateStr}'),'Inbound',${r.received_qty},${esc(r.status)},${esc(r.reference_number)},${r.fulfillment_days||'NULL'},${sk||'NULL'})`);
});
const mvSql = mvRows.length ? `INSERT INTO fact_stock_movements(product_key,zone_key,time_key,supplier_key,movement_type,qty_in,qty_out,net_change,reference_number) VALUES ${mvRows.join(',')}` : 'SELECT 1';
const ordSql = ordRows.length ? `INSERT INTO fact_orders(product_key,time_key,order_type,quantity,status,order_reference,fulfillment_days,supplier_key) VALUES ${ordRows.join(',')}` : 'SELECT 1';
msg.inboundOrderSql = ordSql;
msg.payload = mvSql;
return msg;

