function esc(v){if(v===null||v===undefined)return 'NULL';if(typeof v==='number')return v;return "'"+String(v).replace(/'/g,"''")+"'";}
function fmtDate(d){if(!d)return null;return new Date(d).toISOString().split('T')[0];}
const rows = msg.payload||[];
const pMap = msg.productMap||{};
const zMap = msg.zoneMap||{};
const mvRows = [];
rows.forEach(r => {
  const pk = pMap[String(r.product_id)];
  const zk = zMap[String(r.zone_id)];
  const dateStr = fmtDate(r.fact_date);
  if (!pk||!zk||!dateStr) return;
  const qtyIn = r.qty_change > 0 ? r.qty_change : 0;
  const qtyOut = r.qty_change < 0 ? Math.abs(r.qty_change) : 0;
  mvRows.push(`(${pk},${zk},(SELECT time_key FROM dim_time WHERE full_date='${dateStr}'),NULL,'Adjustment',${qtyIn},${qtyOut},${r.qty_change},${esc(r.reason)})`);
});
const sql = mvRows.length ? `INSERT INTO fact_stock_movements(product_key,zone_key,time_key,supplier_key,movement_type,qty_in,qty_out,net_change,reference_number) VALUES ${mvRows.join(',')}` : 'SELECT 1';
msg.payload = sql;
return msg;

const today = new Date().toISOString().split('T')[0];
msg.todayStr = today;
msg.payload = `SELECT time_key FROM dim_time WHERE full_date = '${today}'`;
return msg;

const rows = msg.payload||[];
if (!rows.length) {
  node.error('No time_key found for today: ' + msg.todayStr + '. Is dim_time seeded through 2027?');
  return null;
}
msg.todayTimeKey = rows[0].time_key;
msg.payload = `DELETE FROM fact_inventory_snapshots WHERE time_key=${msg.todayTimeKey}; SELECT product_key,source_id FROM dim_products WHERE is_current=1`;
return msg;

msg.productMap = {};
(msg.payload||[]).forEach(r => { msg.productMap[r.source_id] = r.product_key; });
msg.payload = 'SELECT zone_key,source_id FROM dim_zones';
return msg;

msg.zoneMap = {};
(msg.payload||[]).forEach(r => { msg.zoneMap[r.source_id] = r.zone_key; });
msg.payload = `
SELECT
  i.product_id, i.zone_id, i.quantity, i.min_threshold,
  p.unit_price
FROM inventory i
JOIN products p ON p.id = i.product_id
ORDER BY i.product_id
`;
return msg;

const rows = msg.payload||[];
const pMap = msg.productMap||{};
const zMap = msg.zoneMap||{};
const tk = msg.todayTimeKey;
const snapRows = [];
rows.forEach(r => {
  const pk = pMap[String(r.product_id)];
  const zk = zMap[String(r.zone_id)];
  if (!pk||!zk) return;
  const isBelowThreshold = r.quantity <= r.min_threshold ? 1 : 0;
  const stockValue = parseFloat((r.quantity * r.unit_price).toFixed(2));
  snapRows.push(`(${pk},${zk},${tk},${r.quantity},${r.min_threshold},${isBelowThreshold},${stockValue})`);
});
if (!snapRows.length) {
  node.warn('No inventory rows to snapshot');
  msg.payload = 'SELECT 1';
  return msg;
}
msg.payload = `INSERT INTO fact_inventory_snapshots(product_key,zone_key,time_key,quantity_on_hand,min_threshold,is_below_threshold,stock_value) VALUES ${snapRows.join(',')}`;
return msg;
